import 'package:flutter/material.dart';import 'package:supabase_flutter/supabase_flutter.dart';import '../widgets/ui.dart';import '../models/roles.dart';import '../data/sai_repository.dart';
class ProfileScreen extends StatelessWidget{const ProfileScreen({super.key,required this.roles,required this.repo});final Set<AppRole> roles;final SaiRepository repo;@override Widget build(BuildContext context){final user=repo.db.auth.currentUser;return SaiPage(title:'حسابي',children:[if(user!=null)FutureBuilder<Map<String,dynamic>?>(future:repo.profile(user.id),builder:(context,s)=>SaiTile(title:s.data?['full_name']?.toString()??'المستخدم',subtitle:user.email,icon:Icons.account_circle_outlined)),const SaiSection(title:'صلاحيات الحساب'),...roles.map((r)=>SaiTile(title:r.arabic,icon:Icons.verified_user_outlined)),SaiTile(title:'تسجيل الخروج',icon:Icons.logout,onTap:()=>Supabase.instance.client.auth.signOut())]);}}
